import './../styles/article.css'


function Article(props) {
    
    const article = props.article;
    const {cartItems, setCartItems} = props;

    function addArticle(article) {
        const existingItem = cartItems.find(item => item.id === article.id);
        if (existingItem) {
            setCartItems(cartIems.map(item => item.id === article.id ? {...item, quantity: item.quantity + 1} : item));
        } else {
             setCartItems([...cartItems, {...article, quantity: 1}]);
        }
    }

    return (
        <div className="card">
            {article.promo &&
                <div className="promo"> 
                    <p>{article.promo ? "Solde" : ""}</p>
                </div>
            }
            <img src={article.image} alt={article.nom} className="card-image"/>
            <p>{article.prix}€</p>
            <p>{article.nom}</p>
            <button onClick={() => addArticle(article)}>Ajouter au panier</button>
        </div>
    )
}
export default Article;
